where del_flag = 0

    and (cust_no like concat('%', #{keyword}, '%')
    or name like concat('%', #{keyword}, '%')
    or contact like concat('%', #{keyword}, '%')
    or phone like concat('%', #{keyword}, '%')
    or industry like concat('%', #{keyword}, '%'))


    and level = #{level}


    and status = #{status}


    and industry = #{industry}

